$ErrorActionPreference='Stop';$server=Split-Path $PSScriptRoot;. ([ScriptBlock]::Create((Get-Content -Raw -Encoding UTF8 (Join-Path $server 'deployment\StableRuntime.ps1'))));$root=Join-Path ([IO.Path]::GetTempPath()) ('ai5-stable-'+[guid]::NewGuid().ToString('N'));try{Initialize-AI5StableRuntime $root 'stable-path';$null=Set-AI5UpdateCandidate 'vNext' 'candidate-path';$failed=Complete-AI5ControlledSwitch ([pscustomobject]@{unit=$true;security=$true;e2e=$false;pwa=$true});if($failed.state-ne'CANDIDATE_FAILED'-or$failed.stableVersion-ne'v42'){throw'failed candidate replaced stable'};$null=Set-AI5UpdateCandidate 'vNext' 'candidate-path';$passed=Complete-AI5ControlledSwitch ([pscustomobject]@{unit=$true;security=$true;e2e=$true;pwa=$true});if($passed.state-ne'STABLE'-or$passed.stableVersion-ne'vNext'-or$passed.stablePath-ne'candidate-path'){throw'controlled switch failed'};'STABLE_RUNTIME_TESTS_OK'}finally{if(Test-Path $root){Remove-Item -LiteralPath $root -Recurse -Force}}
